def seed_sizes(db):
    """Populate only products without sizes, leaving admin changes intact."""
    for code, item in PRODUCT_SIZES.items():
        row=db.execute("SELECT p.id,p.name,b.name AS brand FROM products p JOIN brands b ON b.id=p.brand_id WHERE p.id=?",(code,)).fetchone()
        if not row or row['name']!=item['name'] or row['brand']!=item['brand']:
            continue  # Do not assign incorrect size to repurposed IDs.
        if db.execute('SELECT 1 FROM product_sizes WHERE product_id=? LIMIT 1',(row['id'],)).fetchone():
            continue
        db.executemany('INSERT INTO product_sizes(product_id,size_name,sort_order) VALUES(?,?,?)',[(code,size,idx) for idx,size in enumerate(item['options'])])
